import sys

def lcs_without_virus(s1, s2, virus):
    m, n = len(s1), len(s2)
    dp = [['' for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                candidate = dp[i - 1][j - 1] + s1[i - 1]
                if virus not in candidate:
                    dp[i][j] = candidate
            if len(dp[i - 1][j]) > len(dp[i][j]):
                dp[i][j] = dp[i - 1][j]
            if len(dp[i][j - 1]) > len(dp[i][j]):
                dp[i][j] =dp[i][j - 1]

    result = dp[m][n]
    return result if result else '0'

def main():
    input = sys.stdin.read().splitlines()
    s1, s2, virus = input[0], input[1], input[2]
    print(lcs_without_virus(s1, s2, virus))

if __name__ == "__main__":
    main()
